	playlists core.Playlists, scrobbler scrobbler.PlayTracker, share core.Share, playback playback.PlaybackServer,
) *Router {
	r := &Router{
		ds:               ds,
		artwork:          artwork,
		streamer:         streamer,
		archiver:         archiver,
		players:          players,
		externalMetadata: externalMetadata,
		playlists:        playlists,
		scanner:          scanner,
		broker:           broker,
		scrobbler:        scrobbler,
		share:            share,
		playback:         playback,
	}
	r.Handler = r.routes()
	return r
}

